73	    private final TelephoneNormalizer telephoneNormalizer;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 TelephoneNormalizer telephoneNormalizer,
82	                                 AddressNormalizer addressNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.telephoneNormalizer = telephoneNormalizer;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
120	        rejectBlankOwnerFields(ownerFieldsDto);
121	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
122	        if (!sharesHousehold) {
123	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
124	        }
125	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
126	        rejectDuplicateTelephone(normalizedTelephone);
127	        ownerFieldsDto.setTelephone(normalizedTelephone);
128	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
135	        if (sharesHousehold) {
136	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
137	        }
138	        this.clinicService.saveOwner(owner);
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
157	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    /**
240	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
241	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
242	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
243	     * blank (e.g. {@code "   "}). The offending field names are reported through an
244	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
245	     * as a 400 response carrying an {@code errors} array of field names.
246	     *
247	     * @param ownerFieldsDto the submitted owner fields
248	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
249	     */
250	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
251	        List<String> blankFields = new ArrayList<>();
252	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
253	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
254	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
255	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
256	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
257	        if (!blankFields.isEmpty()) {
258	            throw new InvalidOwnerFieldsException(blankFields);
259	        }
260	    }
261	
262	    private void addIfBlank(List<String> blankFields, String field, String value) {
263	        if (value != null && value.isBlank()) {
264	            blankFields.add(field);
265	        }
266	    }
267	
268	    /**
269	     * Normalizes an owner's optional email address. When present it is stored and returned
270	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
271	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
272	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
273	     * method runs.
274	     *
275	     * @param email the raw email value from the request, or {@code null} when omitted
276	     * @return the lower-cased email, or {@code null} when none was supplied
277	     */
278	    private String normalizeEmail(String email) {
279	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
280	    }
281	
282	    /**
283	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
284	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
285	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
286	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
287	     *
288	     * @param lastName the last name of the owner being created
289	     * @return the formatted customer code
290	     */
291	    private String nextCustomerCode(String lastName) {
292	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
293	        long sequence = this.clinicService.findAllOwners().size() + 1L;
294	        return String.format("%s-%04d", last3, sequence);
295	    }
296	
297	    /**
298	     * Rejects a create request whose normalized telephone is already used by any existing owner.
299	     * Existing owners' telephones are reduced to the same canonical form (via
300	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
301	     * only in formatting still collide. A collision is reported through a
302	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
303	     * as a 409 Conflict response.
304	     *
305	     * @param normalizedTelephone the canonical telephone of the owner being created
306	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
307	     */
308	    private void rejectDuplicateTelephone(String normalizedTelephone) {
309	        boolean duplicate = existingOwnerMatches(
310	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
311	            normalizedTelephone);
312	        if (duplicate) {
313	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
314	        }
315	    }
316	
317	    /**
318	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
319	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
320	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
321	     * and the owner being created to the same canonical key and reject a match.
322	     *
323	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
324	     * @param key the canonical key of the owner being created
325	     * @return {@code true} if some existing owner shares the key
326	     */
327	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
328	        return this.clinicService.findAllOwners().stream()
329	            .map(keyExtractor)
330	            .filter(Objects::nonNull)
331	            .anyMatch(key::equals);
332	    }
333	
334	    /**
335	     * Rejects a create request that shares a household with an existing owner: another owner already
336	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
337	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
338	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
339	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
340	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
341	     * check when the request opts in via {@code sharesHousehold}.
342	     *
343	     * @param lastName the last name of the owner being created
344	     * @param address the address of the owner being created
345	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
346	     */
347	    private void rejectDuplicateHousehold(String lastName, String address) {
348	        String canonicalLastName = canonicalizeHousehold(lastName);
349	        String canonicalAddress = canonicalizeHousehold(address);
350	        if (canonicalLastName == null || canonicalAddress == null) {
351	            return;
352	        }
353	        boolean duplicate = this.clinicService.findAllOwners().stream()
354	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
355	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
356	        if (duplicate) {
357	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
358	        }
359	    }
360	
361	    /**
362	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
363	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
364	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
365	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
366	     *
367	     * @param value the raw field value, or {@code null}
368	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
369	     */
370	    private String canonicalizeHousehold(String value) {
371	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
372	    }
373	
374	    /**
375	     * Derives the stable, shared {@code householdId} for an owner joining a household via
376	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
377	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
378	     * owner with the same last name at the same address - regardless of casing or spacing - is
379	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
380	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
381	     *
382	     * @param lastName the last name of the owner being created
383	     * @param address the address of the owner being created
384	     * @return the shared household identifier
385	     */
386	    private String householdId(String lastName, String address) {
387	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
388	        try {
389	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
390	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
391	            StringBuilder sb = new StringBuilder(digest.length * 2);
392	            for (byte b : digest) {
393	                sb.append(String.format("%02X", b));
394	            }
395	            return sb.substring(0, 16);
396	        } catch (java.security.NoSuchAlgorithmException e) {
397	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
398	        }
399	    }
400	}
